1	"use client";
2	
3	import { useEffect, useMemo, useRef, useState } from "react";
4	import { useRouter } from "next/navigation";
5	import Link from "next/link";
6	import { ArrowLeft, ArrowRight, RotateCcw, Sparkles } from "lucide-react";
7	import { destinationAfterAuth } from "@/lib/pending-prompt";
8	import { getTemplate } from "@/lib/templates";
9	import {
10	  assemblePrompt,
11	  getLook,
12	  EMPTY_ANSWERS,
13	  hasAnswers,
14	  MAX_NAME_CHARS,
15	  MAX_WHAT_CHARS,
16	  stashPrompt,
17	  templatesForCategory,
18	  WIZARD_CATEGORIES,
19	  type WizardAnswers,
20	} from "@/lib/wizard";
21	import { LookPicker } from "./LookPicker";
22	
23	/**
24	 * The prompt wizard.
25	 *
26	 * ## It is a side door, never a gate
27	 *
28	 * The raw composer on the home page is and stays the default: nothing here
29	 * blocks it, nothing here renders on it, and a returning user never sees this
30	 * unless they ask for it. Everything below is skippable — the two question
31	 * screens each carry a Skip, and "Skip to the prompt" on either of them jumps
32	 * straight to the review with whatever has been answered so far. Abandoning
33	 * halfway is a productive action, not a loss.
34	 *
35	 * ## What is deliberately NOT here
36	 *
37	 * The plan's third screen — logo upload, importing your current site, and a
38	 * reference site — is absent rather than disabled. Each of those needs a
39	 * decision this pass is not making (out-of-band logo injection, SSRF controls
40	 * behind a separate egress service, a provenance rule for imported facts), and
41	 * a greyed-out field implying "coming soon" is a promise this code cannot keep.
42	 *
43	 * ## Zero model calls
44	 *
45	 * Assembly is local string work in lib/wizard.ts. There is no /api/enhance call
46	 * here and there should not be one: that route is auth-gated and rate limited
47	 * per user id, and most people meeting this wizard are signed out.
48	 */
49	
50	const STEPS = [
51	  { id: "what", label: "What and who" },
52	  { id: "look", label: "Pick a look" },
53	  { id: "review", label: "Your prompt" },
54	] as const;
55	
56	const LAST = STEPS.length - 1;
57	
58	export function PromptWizard({
59	  signedIn,
60	  creditEstimate,
61	}: {
62	  signedIn: boolean;
63	  /** From estimateCredits("create") on the server — lib/credits.ts pulls in Prisma. */
64	  creditEstimate: { low: number; high: number };
65	}) {
66	  const router = useRouter();
67	  const [step, setStep] = useState(0);
68	  const [answers, setAnswers] = useState<WizardAnswers>(EMPTY_ANSWERS);
69	  /** Non-null once the review textarea has been touched. This is what Revert throws away. */
70	  const [edited, setEdited] = useState<string | null>(null);
71	  const [starting, setStarting] = useState(false);
72	  const [error, setError] = useState<string | null>(null);
73	  const headingRef = useRef<HTMLHeadingElement>(null);
74	  /** Skip the focus move on first paint — nobody asked to be sent anywhere yet. */
75	  const mounted = useRef(false);
76	
77	  const assembled = useMemo(() => assemblePrompt(answers), [answers]);
78	  const promptText = edited ?? assembled;
79	  const matches = templatesForCategory(answers.category);
80	
81	  // Moving between steps swaps the whole panel, so without this a keyboard or
82	  // screen-reader user is left focused on a button that no longer means what it
83	  // did. The sr-only status region below announces the change; this puts the
84	  // caret where the new content starts.
85	  useEffect(() => {
86	    if (!mounted.current) {
87	      mounted.current = true;
88	      return;
89	    }
90	    headingRef.current?.focus();
91	  }, [step]);
92	
93	  /**
94	   * Any change to an answer invalidates a hand-edit of the assembled prompt —
95	   * silently keeping the old text would mean the palette they just changed
96	   * never reaches the build. Dropping the edit is the honest failure: the
97	   * review step is right there and the edit was one screen ago.
98	   */
99	  function update(patch: Partial<WizardAnswers>) {
100	    setAnswers((prev) => ({ ...prev, ...patch }));
101	    setEdited(null);
102	  }
103	
104	  function pickCategory(category: WizardAnswers["category"]) {
105	    const first = templatesForCategory(category)[0];
106	    update({ category, templateId: first?.id ?? null });
107	  }
108	
109	  /**
110	   * Skip means skip: it clears whatever this screen contributed and moves on,
111	   * rather than quietly keeping a half-answer the user just decided against.
112	   * Step 1's fields are all optional, so there is nothing to clear there — it
113	   * is the same as Next, and having the control present matters more than
114	   * having it do something different.
115	   */
116	  function skip() {
117	    if (step === 1) update({ lookId: null });
118	    setStep((s) => s + 1);
119	  }
120	
121	  async function build() {
122	    if (starting) return;
123	    const text = promptText.trim();
124	    if (!text) return;
125	
126	    setStarting(true);
127	    setError(null);
128	
129	    // Hand off through the SAME pending-prompt mechanism the composer and the
130	    // template gallery use, rather than inventing a second route into a build.
131	    // Signed out: /signup shows the prompt back and its submit handler calls
132	    // destinationAfterAuth(). Signed in: we call it directly.
133	    if (!stashPrompt(text)) {
134	      setStarting(false);
135	      setError(
136	        "Your browser is blocking session storage, so the prompt can't travel with you. Copy it somewhere safe first, or try a normal (non-private) window.",
137	      );
138	      return;
139	    }
140	
141	    if (!signedIn) {
142	      router.push("/signup");
143	      return;
144	    }
145	
146	    // Returns "/dashboard" if project creation fails, including a session that
147	    // expired since this page rendered — the prompt stays in sessionStorage
148	    // either way, so nothing is lost. `starting` is deliberately left set:
149	    // every branch navigates, and a locked button stops a double-click
150	    // creating two projects.
151	    const dest = await destinationAfterAuth();
152	    router.push(dest);
153	    router.refresh();
154	  }
155	
156	  return (
157	    <div className="mx-auto w-full max-w-3xl">
158	      {/* Step changes are a whole-panel swap with no page navigation, so they
159	          are invisible to assistive tech unless announced. */}
160	      <p role="status" className="sr-only">
161	        {`Step ${step + 1} of ${STEPS.length}: ${STEPS[step].label}.`}
162	      </p>
163	
164	      <div className="rounded-2xl border border-black/10 bg-white/60 p-6 backdrop-blur-sm sm:p-8 dark:border-white/10 dark:bg-white/[0.02]">
165	        <div className="flex flex-wrap items-center justify-between gap-3">
166	          <p
167	            aria-hidden
168	            className="text-[11px] font-medium uppercase tracking-[0.14em] text-neutral-500 dark:text-neutral-400"
169	          >
170	            Step {step + 1} of {STEPS.length} · {STEPS[step].label}
171	          </p>
172	          <div aria-hidden className="flex items-center gap-1.5">
173	            {STEPS.map((s, i) => (
174	              <span
175	                key={s.id}
176	                className={`h-1.5 rounded-full transition-all ${
177	                  i === step
178	                    ? "w-6 bg-neutral-900 dark:bg-white"
179	                    : i < step
180	                      ? "w-1.5 bg-neutral-900/40 dark:bg-white/40"
181	                      : "w-1.5 bg-black/10 dark:bg-white/15"
182	                }`}
183	              />
184	            ))}
185	          </div>
186	        </div>
187	
188	        {step === 0 && (
189	          <WhatStep
190	            headingRef={headingRef}
191	            answers={answers}
192	            matches={matches}
193	            onPickCategory={pickCategory}
194	            onUpdate={update}
195	          />
196	        )}
197	
198	        {step === 1 && (
199	          <section className="mt-6">
200	            <h2
201	              ref={headingRef}
202	              tabIndex={-1}
203	              className="text-xl font-semibold tracking-tight outline-none focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-[var(--accent)]"
204	            >
205	              Pick a look
206	            </h2>
207	            <div className="mt-5">
208	              <LookPicker value={answers.lookId} onChange={(lookId) => update({ lookId })} />
209	            </div>
210	          </section>
211	        )}
212	
213	        {step === 2 && (
214	          <ReviewStep
215	            headingRef={headingRef}
216	            promptText={promptText}
217	            basis={{
218	              template: (answers.templateId ? getTemplate(answers.templateId) : undefined)?.name ?? null,
219	              look: (answers.lookId ? getLook(answers.lookId) : undefined)?.name ?? null,
220	            }}
221	            edited={edited}
222	            onEdit={setEdited}
223	            onRevert={() => setEdited(null)}
224	            creditEstimate={creditEstimate}
225	            signedIn={signedIn}
226	            starting={starting}
227	            error={error}
228	            onBuild={build}
229	          />
230	        )}
231	
232	        {/* ── Navigation ─────────────────────────────────────────────────── */}
233	        <div className="mt-8 flex flex-col gap-3 border-t border-black/10 pt-6 sm:flex-row sm:items-center sm:justify-between dark:border-white/10">
234	          <div className="flex items-center gap-3">
235	            {step > 0 && (
236	              <button
237	                type="button"
238	                onClick={() => setStep((s) => s - 1)}
239	                className="inline-flex items-center gap-1.5 rounded-lg px-3 py-2 text-sm font-medium text-neutral-600 transition-colors hover:bg-black/5 hover:text-neutral-900 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--accent)] dark:text-neutral-400 dark:hover:bg-white/10 dark:hover:text-white"
240	              >
241	                <ArrowLeft size={14} aria-hidden />
242	                Back
243	              </button>
244	            )}
245	            {/* Only on the first screen. On the second, "Skip this step" already
246	                lands on the review, so a second control saying almost the same
247	                thing would just be two ways to guess. */}
248	            {step === 0 && (
249	              <button
250	                type="button"
251	                onClick={() => setStep(LAST)}
252	                className="rounded-lg px-3 py-2 text-sm text-neutral-500 underline underline-offset-4 transition-colors hover:text-neutral-900 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--accent)] dark:text-neutral-400 dark:hover:text-white"
253	              >
254	                Skip to the prompt
255	              </button>
256	            )}
257	          </div>
258	
259	          {step < LAST && (
260	            <div className="flex items-center gap-2">
261	              <button
262	                type="button"
263	                onClick={skip}
264	                className="rounded-lg px-3 py-2 text-sm font-medium text-neutral-600 transition-colors hover:bg-black/5 hover:text-neutral-900 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--accent)] dark:text-neutral-400 dark:hover:bg-white/10 dark:hover:text-white"
265	              >
266	                Skip this step
267	              </button>
268	              <button
269	                type="button"
270	                onClick={() => setStep((s) => s + 1)}
271	                className="group inline-flex items-center justify-center gap-2 rounded-lg bg-neutral-900 px-5 py-2.5 text-sm font-medium text-white transition-colors hover:bg-neutral-800 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--accent)] dark:bg-white dark:text-neutral-900 dark:hover:bg-neutral-200"
272	              >
273	                Next
274	                <ArrowRight
275	                  size={14}
276	                  aria-hidden
277	                  className="transition-transform group-hover:translate-x-0.5"
278	                />
279	              </button>
280	            </div>
281	          )}
282	        </div>
283	      </div>
284	
285	      {/* The way out. Leaving is never a loss of work while there is any: the
286	          skip controls above hand back everything answered so far as a finished
287	          prompt, and this link goes to the plain box, which is the default entry
288	          point and always was. */}
289	      <p className="mt-5 text-center text-xs text-neutral-500 dark:text-neutral-400">
290	        {hasAnswers(answers) && step < LAST ? (
291	          <>Done answering? Skip ahead for the prompt, or </>
292	        ) : (
293	          <>Would rather just type it? </>
294	        )}
295	        <Link
296	          href="/"
297	          className="underline underline-offset-4 transition-colors hover:text-neutral-900 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-[var(--accent)] dark:hover:text-white"
298	        >
299	          go back to the plain box
300	        </Link>
301	        .
302	      </p>
303	    </div>
304	  );
305	}
306	
307	// ---------------------------------------------------------------------------
308	// Step 1 — what and who
309	// ---------------------------------------------------------------------------
310	
311	function WhatStep({
312	  headingRef,
313	  answers,
314	  matches,
315	  onPickCategory,
316	  onUpdate,
317	}: {
318	  headingRef: React.RefObject<HTMLHeadingElement | null>;
319	  answers: WizardAnswers;
320	  matches: ReturnType<typeof templatesForCategory>;
321	  onPickCategory: (category: WizardAnswers["category"]) => void;
322	  onUpdate: (patch: Partial<WizardAnswers>) => void;
323	}) {
324	  return (
325	    <section className="mt-6">
326	      <h2
327	        ref={headingRef}
328	        tabIndex={-1}
329	        className="text-xl font-semibold tracking-tight outline-none focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-[var(--accent)]"
330	      >
331	        What are you building, and who for?
332	      </h2>
333	
334	      <fieldset className="mt-6">
335	        <legend className="text-sm font-medium">What kind of site is this?</legend>
336	        <p className="mt-1.5 text-sm leading-relaxed text-neutral-600 dark:text-neutral-400">
337	          Kodely loads a starting brief written for that kind of business — the same ones on the{" "}
338	          <Link
339	            href="/templates"
340	            className="underline underline-offset-4 hover:text-neutral-900 dark:hover:text-white"
341	          >
342	            templates page
343	          </Link>
344	          . You read and edit the whole thing at the end.
345	        </p>
346	        <div className="mt-4 flex flex-wrap gap-2">
347	          {WIZARD_CATEGORIES.map((option) => (
348	            <label key={option} className="cursor-pointer">
349	              <input
350	                type="radio"
351	                name="wizard-category"
352	                value={option}
353	                checked={answers.category === option}
354	                onChange={() => onPickCategory(option)}
355	                className="peer sr-only"
356	              />
357	              <span className="inline-flex items-center rounded-full border border-neutral-200 bg-white/50 px-3.5 py-1.5 text-xs text-neutral-600 backdrop-blur-md transition-colors hover:border-neutral-300 hover:text-neutral-900 peer-checked:border-neutral-900 peer-checked:bg-neutral-900 peer-checked:text-white peer-focus-visible:outline-2 peer-focus-visible:outline-offset-2 peer-focus-visible:outline-[var(--accent)] dark:border-white/10 dark:bg-white/[0.04] dark:text-neutral-400 dark:hover:text-white dark:peer-checked:border-white dark:peer-checked:bg-white dark:peer-checked:text-neutral-900">
358	                {option}
359	              </span>
360	            </label>
361	          ))}
362	        </div>
363	      </fieldset>
