    const srv = net.createServer((sock) => {
      seen.push(`CONNECTION to 127.0.0.1:${port}`);
      sock.destroy();
    });
    srv.on("error", () => resolve());
    srv.listen(port, "127.0.0.1", () => {
      tripwires.push(srv);
      resolve();
    });
  });
}
console.log("tripwires listening on:", tripwires.map((s) => s.address().port).join(", ") || "none");

