  "https://2852039166/",
  "https://127.0.0.1/",
  "https://127.0.0.1:443/",
  "https://localhost/",
  "https://[::1]/",
  "https://2130706433/",
  "https://0/",
  "https://0.0.0.0/",
  "https://10.0.0.1/",
  "https://192.168.1.1/",
  "https://172.17.0.1/",
  "https://100.64.0.1/",
  "https://[fd00::1]/",
  "https://[fe80::1]/",
  "https://metadata.google.internal/computeMetadata/v1/",
  "https://kubernetes.default.svc.cluster.local/",
  "https://myapp.local/",
  "file:///etc/passwd",
  "file:///C:/Users/edmem/kodely-prod/.env",
  "gopher://127.0.0.1:6379/_SET%20x%20y",
  "data:text/html,<h1>x</h1>",
  "dict://127.0.0.1:11211/stat",
  "ftp://127.0.0.1/",
  "https://example.com:6379/",
  "https://example.com:8080/",
  "https://admin:hunter2@169.254.169.254/",
  "https://example.com@169.254.169.254/",
];

let allRefused = true;
for (const target of TARGETS) {
  const started = Date.now();
  const result = await fetchSiteHtml(target);
  const ms = Date.now() - started;
