  if (result.ok) allRefused = false;
  console.log(`${verdict.padEnd(20)} ${String(ms).padStart(4)}ms  ${target}`);
}

// ── The resolver's own answers, classified ─────────────────────────────────
for (const name of ["localhost"]) {
  const answers = await dnsLookup(name, { all: true, verbatim: true });
  for (const a of answers) {
    console.log(`resolver says ${name} -> ${a.address}; classifier says`, classifyAddress(a.address));
  }
}

// ── Does the pin actually pin? ─────────────────────────────────────────────
// The six lines of `pinnedLookup`, replicated, pointed at a server built here.
// The hostname is `pinned.invalid`, which cannot resolve at all — so if the
// request lands, it landed because the pinned address was used and not because
// anything looked the name up.
const server = https.createServer(
  {
    // A throwaway self-signed pair generated for this check only.
    key: KEY,
    cert: CERT,
  },
  (req, res) => {
    res.writeHead(200, { "content-type": "text/html" });
    res.end(`<html><body>host header was: ${req.headers.host}</body></html>`);
  },
);
await new Promise((r) => server.listen(0, "127.0.0.1", r));
const port = server.address().port;

await new Promise((resolve) => {
  const req = https.request(
    {
      host: "pinned.invalid",
      servername: "pinned.invalid",
      port,
      path: "/",
      rejectUnauthorized: false, // self-signed; the real fetcher never does this
      agent: false,
      lookup: (_h, options, cb) => {
        if (options && typeof options === "object" && options.all) {
          cb(null, [{ address: "127.0.0.1", family: 4 }]);
        } else {
          cb(null, "127.0.0.1", 4);
        }
      },
      headers: { Host: `pinned.invalid:${port}` },
    },
    (res) => {
      let body = "";
      res.on("data", (c) => (body += c));
      res.on("end", () => {
        console.log("pin test:", body.replace(/<[^>]+>/g, ""), "| socket peer:", res.socket.remoteAddress);
        resolve();
      });
    },
  );
  req.on("error", (e) => {
    console.log("pin test FAILED:", e.message);
    resolve();
  });
  req.end();
});
server.close();

for (const s of tripwires) s.close();
console.log("\ntripwire connections observed:", seen.length ? seen : "none — nothing was dialled");
console.log("every hostile target refused:", allRefused);

