    };
  }

  // Nothing is consumed until every rule has passed, so a request refused by
  // the host rule does not also spend the user's own allowance.
  mine.push(now);
  userHits.set(userId, mine);
  theirs.push(now);
  hostHits.set(host, theirs);
  globalHits.push(now);
  return { allowed: true };
}

